package com.osrsbuddy;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;

@Singleton
public class OsrsBuddyPanel extends PluginPanel
{
    @Inject private OsrsBuddyConfig config;

    private OsrsBuddyPlugin plugin;
    private final JLabel status = new JLabel("Not paired");
    private final JTextField codeField = new JTextField();
    private final JButton pairBtn = new JButton("Pair");
    private final JButton syncBtn = new JButton("Sync now");
    private final JButton unpairBtn = new JButton("Unpair");
    private final JLabel message = new JLabel(" ");

    public void init(OsrsBuddyPlugin plugin)
    {
        this.plugin = plugin;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("OSRSBuddy");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        add(title);
        add(Box.createVerticalStrut(8));

        add(status);
        add(Box.createVerticalStrut(12));

        JLabel hint = new JLabel("<html>Generate a pairing code on<br>osrsbuddy.com → Character page,<br>then paste it below.</html>");
        hint.setForeground(Color.LIGHT_GRAY);
        add(hint);
        add(Box.createVerticalStrut(8));

        codeField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        add(codeField);
        add(Box.createVerticalStrut(6));

        pairBtn.addActionListener(e -> {
            String c = codeField.getText();
            if (c == null || c.trim().isEmpty()) { showError("Enter a pairing code"); return; }
            pairBtn.setEnabled(false);
            plugin.pair(c, () -> SwingUtilities.invokeLater(() -> {
                pairBtn.setEnabled(true);
                refreshStatus();
            }));
        });
        add(pairBtn);
        add(Box.createVerticalStrut(12));

        syncBtn.addActionListener(e -> plugin.manualSync());
        add(syncBtn);
        add(Box.createVerticalStrut(6));

        unpairBtn.addActionListener(e -> plugin.unpair());
        add(unpairBtn);
        add(Box.createVerticalStrut(12));

        message.setForeground(Color.LIGHT_GRAY);
        add(message);

        refreshStatus();
    }

    public void refreshStatus()
    {
        SwingUtilities.invokeLater(() -> {
            boolean paired = plugin != null && plugin.isPaired();
            status.setText(paired ? "Paired ✓" : "Not paired");
            status.setForeground(paired ? new Color(120, 200, 120) : Color.LIGHT_GRAY);
            syncBtn.setEnabled(paired);
            unpairBtn.setEnabled(paired);
            pairBtn.setEnabled(!paired);
            codeField.setEnabled(!paired);
        });
    }

    public void showError(String msg)
    {
        SwingUtilities.invokeLater(() -> {
            message.setForeground(new Color(220, 120, 120));
            message.setText("<html>" + msg + "</html>");
        });
    }

    public void showInfo(String msg)
    {
        SwingUtilities.invokeLater(() -> {
            message.setForeground(Color.LIGHT_GRAY);
            message.setText("<html>" + msg + "</html>");
        });
    }
}

package com.osrsbuddy;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
    name = "OSRSBuddy",
    description = "Sync your character with osrsbuddy.com for personalised AI coaching",
    tags = {"sync", "external", "osrsbuddy", "ai", "coach"}
)
public class OsrsBuddyPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ConfigManager configManager;
    @Inject private ScheduledExecutorService executor;
    @Inject private OsrsBuddyConfig config;
    @Inject private ApiClient api;
    @Inject private OsrsBuddyPanel panel;

    private NavigationButton navButton;

    // Debounce: schedule a single sync in a bit, instead of one-per-event
    private boolean syncPending = false;

    // Last-known data, so we can detect meaningful changes
    private final Map<String, Integer> lastSkillXp = new HashMap<>();
    private final Set<String> lastCompletedQuests = new HashSet<>();
    private String lastRsn = null;

    @Override
    protected void startUp()
    {
        panel.init(this);
        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
        navButton = NavigationButton.builder()
            .tooltip("OSRSBuddy")
            .icon(icon)
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        lastSkillXp.clear();
        lastCompletedQuests.clear();
        lastRsn = null;
    }

    @Provides
    OsrsBuddyConfig provideConfig(ConfigManager cm) { return cm.getConfig(OsrsBuddyConfig.class); }

    // -------- Events --------

    @Subscribe
    public void onGameStateChanged(GameStateChanged ev)
    {
        if (ev.getGameState() == GameState.LOGGED_IN) {
            // Initial sync shortly after login (gives the client time to populate skills/quests)
            scheduleSync(8);
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged ev)
    {
        String name = ev.getSkill().getName();
        Integer prev = lastSkillXp.get(name);
        if (prev == null || ev.getXp() != prev) {
            lastSkillXp.put(name, ev.getXp());
            // Only trigger a sync on level-up (xp delta is too noisy)
            if (prev != null && ev.getLevel() > Experience.getLevelForXp(prev)) {
                scheduleSync(2);
            }
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged ev)
    {
        // Quest, diary, and CA varbits all flow through here.
        // We let the snapshotter re-read them — just debounce.
        scheduleSync(15);
    }

    @Subscribe
    public void onChatMessage(ChatMessage ev)
    {
        if (ev.getType() != ChatMessageType.GAMEMESSAGE && ev.getType() != ChatMessageType.SPAM) return;
        String msg = ev.getMessage().toLowerCase();
        if (msg.contains("your kill count is") || msg.contains("collection log:") ||
            msg.contains("congratulations") && msg.contains("quest") ||
            msg.contains("combat task")) {
            scheduleSync(3);
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged ev)
    {
        if (!config.syncInventory()) return;
        int id = ev.getContainerId();
        if (id == InventoryID.INVENTORY.getId() || id == InventoryID.EQUIPMENT.getId() || id == InventoryID.BANK.getId()) {
            scheduleSync(20);
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged ev)
    {
        if (!OsrsBuddyConfig.GROUP.equals(ev.getGroup())) return;
        if ("apiToken".equals(ev.getKey())) {
            panel.refreshStatus();
        }
    }

    // -------- Public actions (called by the panel) --------

    void pair(String code, Runnable onDone)
    {
        api.claim(code, (token, err) -> {
            if (err != null || token == null) {
                panel.showError(err != null ? err.getMessage() : "Pairing failed");
            } else {
                configManager.setConfiguration(OsrsBuddyConfig.GROUP, "apiToken", token);
                panel.showInfo("Paired! Syncing your character now…");
                scheduleSync(1);
            }
            if (onDone != null) onDone.run();
        });
    }

    void unpair()
    {
        configManager.unsetConfiguration(OsrsBuddyConfig.GROUP, "apiToken");
        panel.refreshStatus();
    }

    void manualSync()
    {
        scheduleSync(0);
    }

    boolean isPaired() { return config.apiToken() != null && !config.apiToken().isEmpty(); }

    // -------- Sync engine --------

    private synchronized void scheduleSync(int delaySeconds)
    {
        if (!isPaired()) return;
        if (syncPending) return;
        syncPending = true;
        executor.schedule(() -> {
            syncPending = false;
            clientThread.invoke(this::doSync);
        }, delaySeconds, TimeUnit.SECONDS);
    }

    private void doSync()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        try {
            Map<String, Object> payload = CharacterSnapshot.build(client, config);
            api.sync(payload, (v, err) -> {
                if (err == null) {
                    panel.showInfo("Synced ✓ " + new Date());
                    Object rsn = payload.get("rsn");
                    if (rsn instanceof String) lastRsn = (String) rsn;
                }
            });
        } catch (Exception e) {
            log.warn("Snapshot failed", e);
        }
    }
}

package com.osrsbuddy;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(OsrsBuddyConfig.GROUP)
public interface OsrsBuddyConfig extends Config
{
    String GROUP = "osrsbuddy";

    @ConfigSection(
        name = "Connection",
        description = "Pair this plugin with your osrsbuddy.com account",
        position = 0
    )
    String connectionSection = "connection";

    @ConfigItem(
        keyName = "apiToken",
        name = "API token",
        description = "Long-lived token issued after pairing. Do not share.",
        section = connectionSection,
        secret = true
    )
    default String apiToken() { return ""; }

    @ConfigItem(keyName = "apiToken", name = "", description = "")
    void setApiToken(String token);

    @ConfigItem(
        keyName = "serverUrl",
        name = "Server URL",
        description = "OSRSBuddy backend (advanced — leave default)",
        section = connectionSection,
        position = 10
    )
    default String serverUrl() { return "https://yljugjbhwmyslhqoitlk.supabase.co/functions/v1"; }

    @ConfigItem(
        keyName = "syncInventory",
        name = "Sync inventory & bank",
        description = "Includes bank, inventory, and equipped gear in syncs",
        position = 20
    )
    default boolean syncInventory() { return true; }

}

package com.osrsbuddy;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/**
 * Thin HTTP client for the two OSRSBuddy edge functions:
 * POST /plugin-claim   (exchange pairing code for an API token)
 * POST /plugin-sync    (push character snapshot)
 */

@Slf4j
@Singleton
public class ApiClient
{
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

    private final OkHttpClient http;
    private final Gson gson;
    private final OsrsBuddyConfig config;

    @Inject
    private ApiClient(OkHttpClient runeliteHttpClient, Gson gson, OsrsBuddyConfig config)
    {
        this.gson = gson;
        this.config = config;

        this.http = runeliteHttpClient.newBuilder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .build();
    }

    public interface Callback<T> { void onResult(T result, Throwable error); }

    /** Exchange pairing code for a long-lived API token. */
    public void claim(String code, Callback<String> cb)
    {
        JsonObject body = new JsonObject();
        body.addProperty("code", code.trim());
        body.addProperty("label", "RuneLite — " + System.getProperty("os.name"));

        Request req = new Request.Builder()
            .url(config.serverUrl() + "/plugin-claim")
            .post(RequestBody.create(JSON, gson.toJson(body)))
            .build();

        http.newCall(req).enqueue(new okhttp3.Callback() {
            @Override public void onFailure(Call call, IOException e) { cb.onResult(null, e); }
            @Override public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody rb = response.body()) {
                    String s = rb != null ? rb.string() : "";
                    if (!response.isSuccessful()) {
                        cb.onResult(null, new IOException("Pairing failed (" + response.code() + "): " + s));
                        return;
                    }
                    JsonObject obj = gson.fromJson(s, JsonObject.class);
                    String token = obj.has("token") ? obj.get("token").getAsString() : null;
                    if (token == null) { cb.onResult(null, new IOException("No token in response")); return; }
                    cb.onResult(token, null);
                }
            }
        });
    }

    /** Push a partial character snapshot. Silently no-ops if not paired. */
    public void sync(Map<String, Object> payload, Callback<Void> cb)
    {
        String token = config.apiToken();
        if (token == null || token.isEmpty()) {
            if (cb != null) cb.onResult(null, new IllegalStateException("Not paired"));
            return;
        }

        Request req = new Request.Builder()
            .url(config.serverUrl() + "/plugin-sync")
            .header("Authorization", "Bearer " + token)
            .post(RequestBody.create(JSON, gson.toJson(payload)))
            .build();

        http.newCall(req).enqueue(new okhttp3.Callback() {
            @Override public void onFailure(Call call, IOException e) {
                log.warn("OSRSBuddy sync failed", e);
                if (cb != null) cb.onResult(null, e);
            }
            @Override public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody rb = response.body()) {
                    if (!response.isSuccessful()) {
                        String s = rb != null ? rb.string() : "";
                        log.warn("OSRSBuddy sync HTTP {}: {}", response.code(), s);
                        if (cb != null) cb.onResult(null, new IOException("HTTP " + response.code()));
                        return;
                    }
                    if (cb != null) cb.onResult(null, null);
                }
            }
        });
    }
}

package com.osrsbuddy;

import net.runelite.api.*;
import net.runelite.api.vars.AccountType;

import java.util.*;

/**
 * Reads the live game state and produces the JSON payload accepted by /plugin-sync.
 * Must be called on the client thread.
 */
public final class CharacterSnapshot
{
    private CharacterSnapshot() {}

    public static Map<String, Object> build(Client client, OsrsBuddyConfig config)
    {
        Map<String, Object> out = new LinkedHashMap<>();

        // RSN
        Player local = client.getLocalPlayer();
        if (local != null && local.getName() != null) out.put("rsn", local.getName());

        // Account type
        AccountType acc = client.getAccountType();
        if (acc != null) out.put("account_type", mapAccountType(acc));

        // Skills (level + xp)
        Map<String, Object> skills = new LinkedHashMap<>();
        for (Skill s : Skill.values()) {
            if (s == Skill.OVERALL) continue;
            Map<String, Integer> obj = new LinkedHashMap<>();
            obj.put("level", client.getRealSkillLevel(s));
            obj.put("xp", client.getSkillExperience(s));
            skills.put(s.getName().toLowerCase(), obj);
        }
        out.put("skills", skills);

        // Quests — completed only
        List<String> quests = new ArrayList<>();
        for (Quest q : Quest.values()) {
            try {
                if (q.getState(client) == QuestState.FINISHED) {
                    quests.add(q.getName());
                }
            } catch (Exception ignored) { /* some quest varbits unavailable */ }
        }
        out.put("quests", quests);

        // Inventory + equipment + bank (optional)
        if (config.syncInventory()) {
            List<Map<String, Object>> gear = new ArrayList<>();
            ItemContainer eq = client.getItemContainer(InventoryID.EQUIPMENT);
            if (eq != null) {
                for (Item it : eq.getItems()) {
                    if (it.getId() <= 0) continue;
                    gear.add(itemMap(it));
                }
            }
            out.put("gear", gear);

            Map<String, Object> inv = new LinkedHashMap<>();
            inv.put("inventory", containerItems(client.getItemContainer(InventoryID.INVENTORY)));
            inv.put("bank", containerItems(client.getItemContainer(InventoryID.BANK)));
            out.put("inventory", inv);
        }

        return out;
    }

    private static List<Map<String, Object>> containerItems(ItemContainer c)
    {
        List<Map<String, Object>> list = new ArrayList<>();
        if (c == null) return list;
        for (Item it : c.getItems()) {
            if (it.getId() <= 0) continue;
            list.add(itemMap(it));
        }
        return list;
    }

    private static Map<String, Object> itemMap(Item it)
    {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("id", it.getId());
        m.put("quantity", it.getQuantity());
        return m;
    }

    private static String mapAccountType(AccountType acc)
    {
        switch (acc.name()) {
            case "IRONMAN": return "ironman";
            case "HARDCORE_IRONMAN": return "hcim";
            case "ULTIMATE_IRONMAN": return "uim";
            case "GROUP_IRONMAN":
            case "HARDCORE_GROUP_IRONMAN":
            case "UNRANKED_GROUP_IRONMAN":
                return "gim";
            default: return "main";
        }
    }
}
